// Linely web — AI speech. Two engines:
//   1. "自然音色" — neural voices generated by the server (/api/tts) and played as mp3. Sounds like a real person.
//   2. "设备语音" — the browser's built-in voices, used as a fallback (the best-sounding installed voice is picked automatically).
// Tone presets + speed / pitch / volume work on both. Used by calls, "read aloud" and auto-read.
import { h } from './lib.js';
import { touch, toast } from './state.js';
import { modal, switchEl } from './core.js';

/** set by the call screen so chat auto-read doesn't talk over a call */
export const callState = { active: false };
const synth = window.speechSynthesis || null;
let deviceVoices = [];
const loadDeviceVoices = () => { deviceVoices = synth ? synth.getVoices() : []; };
if (synth) { loadDeviceVoices(); if (synth.addEventListener) synth.addEventListener('voiceschanged', loadDeviceVoices); }

/** Tone presets: mild on purpose — big pitch shifts are what makes speech sound robotic. */
export const PRESETS = {
  default: { name: '自然', rate: 1, pitch: 1, style: '' }, gentle: { name: '温柔', rate: 0.94, pitch: 1.05, style: 'gentle' }, lively: { name: '活泼', rate: 1.1, pitch: 1.1, style: 'cheerful' },
  calm: { name: '沉稳', rate: 0.95, pitch: 0.92, style: 'calm' }, sweet: { name: '甜美', rate: 1.02, pitch: 1.15, style: 'affectionate' }, teen: { name: '少年', rate: 1.06, pitch: 1, style: 'cheerful' },
  slow: { name: '慢读', rate: 0.8, pitch: 1, style: '' }, news: { name: '播音', rate: 1.05, pitch: 1, style: 'newscast' },
};
export const voiceOf = (p) => ({ engine: 'auto', neural: '', uri: '', preset: 'default', rate: 1, pitch: 1, volume: 1, auto: false, ...((p && p.voice) || {}), gender: (p && p.gender) || '' });

// ───────────── neural voices (server) ─────────────
const neural = { loaded: null, enabled: false, voices: [], downUntil: 0, warned: false };
export function loadNeural() {
  if (!neural.loaded) {
    neural.loaded = fetch('/api/tts/voices', { credentials: 'same-origin', cache: 'no-store' }).then((r) => (r.ok ? r.json() : {})).then((j) => { neural.enabled = !!j.enabled; neural.voices = j.voices || []; }).catch(() => {});
  }
  return neural.loaded;
}
loadNeural();
export const neuralAvailable = () => neural.enabled && Date.now() > neural.downUntil;
export function neuralVoices(lang = 'zh-CN') {
  const pre = lang.slice(0, 2).toLowerCase();
  return neural.voices.filter((v) => v.lang.toLowerCase().startsWith(pre)).sort((a, b) => (b.lang === lang) - (a.lang === lang));
}
function pickNeural(cfg, lang) {
  const list = neuralVoices(lang);
  if (cfg.neural && neural.voices.some((v) => v.id === cfg.neural)) return neural.voices.find((v) => v.id === cfg.neural);
  const male = cfg.gender === '男';
  return list.find((v) => v.gender === (male ? 'male' : 'female')) || list[0] || neural.voices[0] || null;
}

// ───────────── device voices (fallback) ─────────────
export const ttsSupported = () => !!synth || neural.enabled;
export function listVoices(lang = 'zh-CN') {
  const pref = lang.slice(0, 2).toLowerCase();
  return [...deviceVoices.filter((v) => v.lang.toLowerCase().startsWith(pref)), ...deviceVoices.filter((v) => !v.lang.toLowerCase().startsWith(pref))];
}
/** score installed voices: online/neural/premium voices sound far better than the default "compact" ones */
function voiceScore(v, lang) {
  const n = v.name.toLowerCase(), l = v.lang.toLowerCase().replace('_', '-'), want = lang.toLowerCase();
  let s = l === want ? 60 : l.startsWith(want.slice(0, 2)) ? 30 : -100;
  if (/natural|neural|online/.test(n)) s += 100;
  if (/premium|enhanced|siri|高质量|增强/.test(n)) s += 80;
  if (/google/.test(n)) s += 40;
  if (/xiaoxiao|xiaoyi|yunxi|晓晓|晓伊|nanami|ting-?ting|mei-?jia|sin-?ji|kyoko|samantha/.test(n)) s += 20;
  if (v.localService === false) s += 10;
  return s;
}
function pickVoice(cfg, lang) {
  if (cfg.uri) { const x = deviceVoices.find((v) => v.voiceURI === cfg.uri); if (x) return x; }
  return [...deviceVoices].sort((a, b) => voiceScore(b, lang) - voiceScore(a, lang)).find((v) => voiceScore(v, lang) > -50) || null;
}

/** Strip markers, markdown, links and emoji so the voice doesn't read them out. */
export function cleanForSpeech(t) {
  return String(t || '').replace(/\[\[[^\]]*\]\]/g, '').replace(/\[(?:红包|转账)\|[^\]]*\]/g, '').replace(/https?:\/\/\S+/g, '')
    .replace(/[*_`#>]+/g, '').replace(/[\p{Extended_Pictographic}\uFE0F\u200D]/gu, '').replace(/[~～]+/g, '，').replace(/\.{3,}|…+/g, '……').replace(/\s+/g, ' ').trim();
}
function sentences(text) { return text.split(/(?<=[。！？!?；;…\n])/).map((s) => s.trim()).filter(Boolean); }
/** first clip is short so audio starts quickly; later clips are longer so prosody flows */
function clips(text, max = 110) {
  const out = [];
  for (const s of sentences(text)) {
    if (out.length && out.length > 1 && out[out.length - 1].length + s.length <= max) out[out.length - 1] += s;
    else if (out.length === 1 && out[0].length < 14 && out[0].length + s.length <= max) out[0] += s; // avoid a tiny first clip like "嗯。"
    else if (out.length && out[out.length - 1].length + s.length <= max && out.length > 1) out[out.length - 1] += s;
    else out.push(s);
  }
  return out.flatMap((s) => (s.length <= 220 ? [s] : s.match(/.{1,160}/gs)));
}

// ───────────── playback ─────────────
const player = new Audio(); player.preload = 'auto';
const SILENT = (() => { const b = new Uint8Array(46); const dv = new DataView(b.buffer); const w = (o, s) => [...s].forEach((c, i) => { b[o + i] = c.charCodeAt(0); });
  w(0, 'RIFF'); dv.setUint32(4, 38, true); w(8, 'WAVE'); w(12, 'fmt '); dv.setUint32(16, 16, true); dv.setUint16(20, 1, true); dv.setUint16(22, 1, true); dv.setUint32(24, 8000, true); dv.setUint32(28, 16000, true); dv.setUint16(32, 2, true); dv.setUint16(34, 16, true); w(36, 'data'); dv.setUint32(40, 2, true);
  return URL.createObjectURL(new Blob([b], { type: 'audio/wav' })); })();
let ticket = 0, speaking = false; const waiters = new Set(); const aborts = new Set();
export const isSpeaking = () => speaking || (!!synth && (synth.speaking || synth.pending));
export function stopSpeaking() {
  ticket++; speaking = false;
  aborts.forEach((a) => a.abort()); aborts.clear();
  try { player.pause(); } catch { /* ignore */ }
  waiters.forEach((r) => r()); waiters.clear();
  if (synth) synth.cancel();
}
/** iOS / Safari only allow audio after a tap — call this inside a click handler once (calls and the voice dialog do). */
export function unlockTTS() {
  try { player.src = SILENT; player.play().catch(() => {}); } catch { /* ignore */ }
  try { if (synth) { const u = new SpeechSynthesisUtterance(' '); u.volume = 0; synth.speak(u); } } catch { /* ignore */ }
}
const playBlob = (blob, volume, onPlay) => new Promise((resolve, reject) => {
  const url = URL.createObjectURL(blob);
  const done = () => { waiters.delete(done); player.onended = player.onerror = player.onplaying = null; URL.revokeObjectURL(url); resolve(); };
  waiters.add(done);
  player.onended = done; player.onerror = () => { waiters.delete(done); URL.revokeObjectURL(url); reject(new Error('audio error')); };
  player.onplaying = () => { player.onplaying = null; if (onPlay) onPlay(); };
  player.src = url; player.volume = Math.max(0, Math.min(1, volume == null ? 1 : volume));
  player.play().catch((e) => { waiters.delete(done); URL.revokeObjectURL(url); reject(e); });
});

// the first tap anywhere unlocks audio playback for the rest of the session (required on iOS / Safari)
document.addEventListener('pointerdown', () => unlockTTS(), { once: true, capture: true });

const prosody = (cfg) => ({
  rate: Math.max(-50, Math.min(50, Math.round(((cfg.rate || 1) - 1) * 100))),
  pitch: Math.max(-40, Math.min(40, Math.round(((cfg.pitch == null ? 1 : cfg.pitch) - 1) * 40))),
  volume: Math.max(-50, Math.min(0, Math.round(((cfg.volume == null ? 1 : cfg.volume) - 1) * 100))),
});
async function speakNeural(my, parts, cfg, lang, { onStart, onSentence }) {
  const voice = pickNeural(cfg, lang); if (!voice) throw new Error('no neural voice');
  const style = voice.styles ? (PRESETS[cfg.preset] || {}).style || '' : '';
  const pr = prosody(cfg);
  const fetchClip = (text) => {
    const ac = new AbortController(); aborts.add(ac);
    return fetch('/api/tts', { method: 'POST', credentials: 'same-origin', headers: { 'Content-Type': 'application/json' }, signal: ac.signal, body: JSON.stringify({ text, voice: voice.id, style, ...pr }) })
      .then((r) => { if (!r.ok) throw new Error('tts ' + r.status); return r.blob(); }).finally(() => aborts.delete(ac));
  };
  const jobs = parts.map(() => null);
  const start = (i) => { if (i < parts.length && !jobs[i]) { jobs[i] = fetchClip(parts[i]); jobs[i].catch(() => {}); } };
  start(0); start(1);
  let started = false;
  for (let i = 0; i < parts.length; i++) {
    let blob;
    try { blob = await jobs[i]; } catch (e) { if (my !== ticket) return { done: true }; return { done: false, rest: parts.slice(i).join(''), err: e }; }
    if (my !== ticket) return { done: true };
    start(i + 1); start(i + 2);
    if (onSentence) onSentence(parts[i]);
    speaking = true;
    try { await playBlob(blob, cfg.volume, () => { if (!started) { started = true; if (onStart) onStart(); } }); }
    catch (e) { if (my !== ticket) return { done: true }; return { done: false, rest: parts.slice(i).join(''), err: e }; }
    if (my !== ticket) return { done: true };
  }
  speaking = false; return { done: true };
}
async function speakDevice(my, parts, cfg, lang, { onStart, onSentence }) {
  if (!synth) return;
  await new Promise((r) => setTimeout(r, 40));
  const voice = pickVoice(cfg, lang); let started = false;
  for (const c of parts.flatMap((s) => (s.length <= 90 ? [s] : s.match(/.{1,80}/gs)))) {
    if (my !== ticket) return;
    if (onSentence) onSentence(c);
    await new Promise((resolve) => {
      const u = new SpeechSynthesisUtterance(c);
      u.lang = voice ? voice.lang : lang; if (voice) { try { u.voice = voice; } catch { /* unsupported voice object */ } }
      u.rate = Math.max(0.5, Math.min(2, cfg.rate || 1)); u.pitch = Math.max(0, Math.min(2, cfg.pitch == null ? 1 : cfg.pitch)); u.volume = Math.max(0, Math.min(1, cfg.volume == null ? 1 : cfg.volume));
      const done = () => { clearTimeout(guard); resolve(); };
      const guard = setTimeout(done, 8000 + c.length * 450);
      u.onstart = () => { if (!started) { started = true; if (onStart) onStart(); } };
      u.onend = done; u.onerror = done;
      synth.speak(u);
    });
  }
}

/** Speaks `text`. Resolves when finished or stopped. Neural voice first; falls back to the device voice if the cloud is unreachable. */
export async function speak(text, cfg = voiceOf(null), opts = {}) {
  const lang = opts.lang || 'zh-CN', body = cleanForSpeech(text); if (!body) return;
  const my = ++ticket; aborts.forEach((a) => a.abort()); aborts.clear(); waiters.forEach((r) => r()); waiters.clear(); try { player.pause(); } catch { /* ignore */ } if (synth) synth.cancel();
  await loadNeural(); if (my !== ticket) return;
  let parts = clips(body);
  if (cfg.engine !== 'device' && neuralAvailable()) {
    const r = await speakNeural(my, parts, cfg, lang, opts);
    if (r.done || my !== ticket) { speaking = false; return; }
    neural.downUntil = Date.now() + 5 * 60 * 1000; speaking = false;
    if (!neural.warned) { neural.warned = true; toast('云端自然语音暂时连不上，已改用设备语音'); }
    parts = clips(r.rest);
  }
  if (!synth) { speaking = false; return; }
  await speakDevice(my, parts, cfg, lang, opts); if (my === ticket) speaking = false;
}

// ───────────── settings dialog ─────────────
export function openVoiceSettings(p, { lang = 'zh-CN', onChange } = {}) {
  unlockTTS();
  const v = { ...voiceOf(p) }; delete v.gender; p.voice = v;
  const save = () => { p.voice = v; touch(); if (onChange) onChange(v); };
  const matchPreset = () => Object.entries(PRESETS).find(([, x]) => Math.abs(x.rate - v.rate) < 0.01 && Math.abs(x.pitch - v.pitch) < 0.01)?.[0] || 'custom';
  const slider = (min, max, step, key, fmt) => {
    const lab = h('b', { class: 'val' }, fmt(v[key])), inp = h('input', { type: 'range', class: 'slider', min, max, step, value: v[key], 'aria-label': key });
    inp.addEventListener('input', () => { v[key] = Number(inp.value); v.preset = matchPreset(); lab.textContent = fmt(v[key]); drawPresets(); save(); });
    return { lab, inp };
  };
  const rate = slider(0.5, 1.6, 0.05, 'rate', (x) => x.toFixed(2) + '×'), pitch = slider(0.7, 1.4, 0.05, 'pitch', (x) => x.toFixed(2)), vol = slider(0.1, 1, 0.05, 'volume', (x) => Math.round(x * 100) + '%');
  const presetBox = h('div');
  function drawPresets() {
    presetBox.replaceChildren(h('div', { class: 'chips' }, ...Object.entries(PRESETS).map(([k, x]) => h('button', { class: 'ch bounce' + (v.preset === k ? ' on' : ''), onClick: () => {
      v.preset = k; v.rate = x.rate; v.pitch = x.pitch; rate.inp.value = x.rate; pitch.inp.value = x.pitch; rate.lab.textContent = x.rate.toFixed(2) + '×'; pitch.lab.textContent = x.pitch.toFixed(2); drawPresets(); save(); sample();
    } }, x.name))));
  }
  const engineBox = h('div'), voiceBox = h('div');
  const useNeural = () => v.engine !== 'device' && neural.enabled;
  function drawEngine() {
    const on = useNeural();
    engineBox.replaceChildren(h('div', { class: 'chips' },
      h('button', { class: 'ch bounce' + (on ? ' on' : ''), onClick: () => { v.engine = 'auto'; save(); drawEngine(); drawVoice(); } }, '自然音色 · 云端'),
      h('button', { class: 'ch bounce' + (!on ? ' on' : ''), onClick: () => { v.engine = 'device'; save(); drawEngine(); drawVoice(); } }, '设备语音')),
      neural.enabled ? null : h('div', { class: 'hint', style: 'margin:6px 0 0' }, '服务器没有开启云端自然音色，现在使用设备语音。'));
  }
  function drawVoice() {
    const sel = h('select', { 'aria-label': '选择声音' });
    if (useNeural()) {
      const list = neuralVoices(lang);
      sel.replaceChildren(h('option', { value: '' }, '自动（按角色性别选择）'), ...list.map((x) => h('option', { value: x.id }, `${x.name} · ${x.desc}`)));
      sel.value = v.neural || ''; sel.addEventListener('change', () => { v.neural = sel.value; save(); sample(); });
    } else {
      const fill = () => { sel.replaceChildren(h('option', { value: '' }, '自动（挑选最好听的）'), ...listVoices(lang).map((x) => h('option', { value: x.voiceURI }, `${x.name} · ${x.lang}`))); sel.value = v.uri || ''; };
      fill(); setTimeout(fill, 600); sel.addEventListener('change', () => { v.uri = sel.value; save(); sample(); });
    }
    voiceBox.replaceChildren(h('label', { class: 'fld' }, h('span', null, '声音'), sel));
  }
  const sample = () => { stopSpeaking(); speak(`你好呀，我是${p.name || 'AI'}。今天也想多听听你说话，你慢慢讲，我在听。`, { ...v, gender: p.gender || '' }, { lang }); };
  drawPresets(); drawEngine(); drawVoice(); loadNeural().then(() => { drawEngine(); drawVoice(); });
  return modal({
    title: `${p.name || 'AI'} 的声音`,
    body: [
      h('b', { class: 'lbl' }, '语音引擎'), engineBox, voiceBox,
      h('b', { class: 'lbl' }, '语气'), presetBox,
      h('b', { class: 'lbl' }, '语速'), h('div', { class: 'srow' }, rate.inp, rate.lab),
      h('b', { class: 'lbl' }, '音调'), h('div', { class: 'srow' }, pitch.inp, pitch.lab),
      h('b', { class: 'lbl' }, '音量'), h('div', { class: 'srow' }, vol.inp, vol.lab),
      h('div', { class: 'setting' }, h('div', { class: 't' }, h('b', null, 'AI 新消息自动朗读'), h('small', null, '聊天时收到回复就读出来')), switchEl(!!v.auto, (x) => { v.auto = x; save(); })),
      h('button', { class: 'btn bounce soft', onClick: sample }, '试听一下')],
    actions: [{ label: '完成', kind: 'p', onClick: () => { stopSpeaking(); } }], onClose: () => stopSpeaking(),
  });
}
